/* Speculative Score-Draft Starter */

// Gated Reverb is key for the snare.
const snareVerb = new Tone.GatedReverb({ roomSize: 0.8, wet: 1.0 }).toDestination();
snareVerb.gate.value = -30; // Set gate threshold to cut the tail.

const kick = new Tone.MembraneSynth({
  pitchDecay: 0.03,
  octaves: 8,
  oscillator: { type: "sine" },
  envelope: { attack: 0.001, decay: 0.4, sustain: 0.01, release: 0.2 },
  volume: -4
}).toDestination();

const snare = new Tone.NoiseSynth({
  noise: { type: "white" },
  envelope: { attack: 0.001, decay: 0.25, sustain: 0 },
  volume: -6
}).connect(snareVerb);

const hihat = new Tone.MetalSynth({
  frequency: 250,
  envelope: { attack: 0.001, decay: 0.08, release: 0.01 },
  harmonicity: 5.1,
  modulationIndex: 32,
  resonance: 4000,
  volume: -18
}).toDestination();

// Example loops:
new Tone.Loop(time => { kick.triggerAttackRelease("C1", "8n", time); }, "4n").start(0);
const snarePattern = new Tone.Pattern(time => { snare.triggerAttack(time); }, [null, "C4", null, "C4"], "4n").start(0);
const hihatPattern = new Tone.Loop(time => { hihat.triggerAttack(time); }, "8n").start(0);

